-- =============================================================================
-- 03_seed_job_db.sql : JOB SERVICE SEED DATA (job_db)
-- 10 Companies (khớp UUID company_id trong clean_and_sync_users.sql)
-- + 12 JobCategories + 24 JobLocations + 120 Jobs (84 APPROVED, 12 PENDING, 12 REJECTED, 12 CLOSED) + 360 JobSkills
-- =============================================================================

CREATE TABLE IF NOT EXISTS companies (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    tax_code VARCHAR(13) NOT NULL UNIQUE,
    industry VARCHAR(255),
    size VARCHAR(20),
    address VARCHAR(500),
    city VARCHAR(100),
    website VARCHAR(255),
    logo_url VARCHAR(500),
    description TEXT,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    created_by VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS job_categories (
    id UUID PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(150) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS job_locations (
    id UUID PRIMARY KEY,
    code VARCHAR(50) NOT NULL UNIQUE,
    city VARCHAR(100) NOT NULL,
    district VARCHAR(150),
    country VARCHAR(100) NOT NULL DEFAULT 'Việt Nam'
);

CREATE TABLE IF NOT EXISTS jobs (
    id UUID PRIMARY KEY,
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    title VARCHAR(255) NOT NULL,
    position VARCHAR(255) NOT NULL,
    level VARCHAR(20) NOT NULL,
    type VARCHAR(20) NOT NULL,
    quantity INT NOT NULL DEFAULT 1,
    city VARCHAR(100),
    address VARCHAR(500),
    work_mode VARCHAR(20) NOT NULL DEFAULT 'ONSITE',
    salary_min NUMERIC(15,0),
    salary_max NUMERIC(15,0),
    description TEXT,
    requirements TEXT,
    benefits TEXT,
    deadline DATE NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
    rejected_reason VARCHAR(1000),
    created_by VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_jobs_company_status ON jobs(company_id, status);

CREATE TABLE IF NOT EXISTS job_skills (
    job_id UUID NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    skill_id VARCHAR(64) NOT NULL,
    skill_code VARCHAR(64),
    skill_name VARCHAR(255) NOT NULL,
    required BOOLEAN NOT NULL DEFAULT TRUE,
    min_score INT NOT NULL DEFAULT 0,
    PRIMARY KEY (job_id, skill_id)
);
CREATE INDEX IF NOT EXISTS idx_job_skills_job ON job_skills(job_id);

CREATE TABLE IF NOT EXISTS match_scores (
    job_id UUID NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    user_id UUID NOT NULL,
    score NUMERIC(5,1) NOT NULL,
    below_minimum BOOLEAN NOT NULL DEFAULT FALSE,
    detail TEXT,
    stale BOOLEAN NOT NULL DEFAULT FALSE,
    computed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (job_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_match_scores_user ON match_scores(user_id);

-- 1. 10 Companies
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, industry = EXCLUDED.industry, size = EXCLUDED.size, status = EXCLUDED.status, updated_at = NOW();

-- 2. 12 Job Categories
ON CONFLICT (code) DO NOTHING;

-- 3. 24 Job Locations
ON CONFLICT (code) DO NOTHING;

-- 4. 120 Jobs (84 APPROVED [70%], 12 PENDING [10%], 12 REJECTED [10%], 12 CLOSED [10%])
